import{_ as a,o as t,c as n,ai as s}from"./chunks/framework.Cabe_Szf.js";const g=JSON.parse('{"title":"Exécutions","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/fr/guide/runs.html"}]]},"headers":[],"relativePath":"fr/guide/runs.md","filePath":"fr/guide/runs.md","lastUpdated":1792397420000}'),l={name:"fr/guide/runs.md"};function r(o,e,i,u,p,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="executions" tabindex="-1">Exécutions <a class="header-anchor" href="#executions" aria-label="Permalink to &quot;Exécutions&quot;">​</a></h1><p><strong>Exécutions</strong> dessine les appels d&#39;un outil au modèle, du début à la fin, en cascade : où le temps est passé, appel par appel, et ce que chaque appel a envoyé et reçu.</p><p><strong>Élément de la barre latérale :</strong> Exécutions (sous En direct) <strong>Route :</strong> <code>/runs</code><strong>Ajouté dans :</strong> v0.8.7 (octobre 2026) <strong>Nécessite :</strong> des appels sur la page En direct. Pointez un outil vers <code>http://localhost:11435</code> et laissez-le travailler. Pour voir ce que chaque appel a envoyé et reçu, activez d&#39;abord <strong>Conserver le texte de l&#39;invite</strong> sur la page En direct.</p><h2 id="a-quoi-ca-sert" tabindex="-1">À quoi ça sert ? <a class="header-anchor" href="#a-quoi-ca-sert" aria-label="Permalink to &quot;À quoi ça sert ?&quot;">​</a></h2><p>Un agent sur un modèle local est lent, et la question est toujours : où ? Dans le modèle ? À le charger ? À relire une invite déjà lue ? Dans les outils entre deux appels ? En direct montre chaque appel de chaque outil au moment où il passe ; Exécutions prend les appels d&#39;un outil et les pose dans le temps, pour que la partie lente saute aux yeux.</p><h2 id="ce-qu-est-une-execution" tabindex="-1">Ce qu&#39;est une exécution <a class="header-anchor" href="#ce-qu-est-une-execution" aria-label="Permalink to &quot;Ce qu&#39;est une exécution&quot;">​</a></h2><p>Une exécution, ce sont les appels d&#39;un outil qui se suivent à moins de deux minutes d&#39;intervalle. Une pause plus longue commence une nouvelle exécution. À l&#39;intérieur, une <strong>étape</strong> commence là où l&#39;outil a entamé une nouvelle conversation : avec le texte conservé, c&#39;est là où l&#39;appel suivant cesse de reprendre la conversation précédente ; sans lui, là où une invite qui valait la peine d&#39;être gardée a trouvé le cache vide alors que le modèle était resté chargé.</p><h2 id="lire-la-cascade" tabindex="-1">Lire la cascade <a class="header-anchor" href="#lire-la-cascade" aria-label="Permalink to &quot;Lire la cascade&quot;">​</a></h2><p>Une ligne par appel au modèle, placée dans le temps. La barre de chaque appel est découpée selon ce que rapporte Ollama :</p><ul><li><strong>Attente</strong> : le temps passé par l&#39;appel avant qu&#39;Ollama ne s&#39;en occupe, plus tout ce qu&#39;Ollama n&#39;a pas comptabilisé.</li><li><strong>Chargement du modèle</strong> : le modèle n&#39;était pas en mémoire. Souvent le plus gros coût d&#39;une exécution.</li><li><strong>Lecture de l&#39;invite</strong> : la partie de l&#39;invite qui n&#39;était pas dans le cache. La partie en cache ne coûte presque rien, elle n&#39;apparaît donc pas comme du temps ; sa part est écrite dans la colonne Opération.</li><li><strong>Écriture de la réponse</strong>.</li></ul><p>Entre deux appels, une ligne <strong>outils</strong> est le temps entre la réponse du modèle et l&#39;appel suivant de l&#39;outil, nommée d&#39;après les outils demandés par le modèle. Une ligne <strong>agent</strong> est le même écart quand aucun outil n&#39;a été demandé : le travail propre de l&#39;outil. Le temps des outils est mesuré de l&#39;extérieur ; rien à l&#39;intérieur d&#39;un outil n&#39;est tracé.</p><p>Des marques en rouge disent ce qui s&#39;est mal passé sur un appel : <strong>modèle chargé</strong>, <strong>cache vide</strong>, <strong>refusé</strong> (l&#39;invite dépassait le contexte chargé), <strong>erreur</strong>.</p><h2 id="ce-que-chaque-ligne-ouvre" tabindex="-1">Ce que chaque ligne ouvre <a class="header-anchor" href="#ce-que-chaque-ligne-ouvre" aria-label="Permalink to &quot;Ce que chaque ligne ouvre&quot;">​</a></h2><p>Cliquez sur une ligne et le panneau de droite la montre.</p><ul><li><strong>Un appel au modèle</strong> : ses chiffres et ses phases, puis <strong>Entrée</strong> (ce qui a été envoyé : la conversation, les schémas d&#39;outils, avec l&#39;endroit où l&#39;invite a cessé de correspondre à l&#39;appel précédent) et <strong>Sortie</strong> (ce qui est revenu : la réponse, la réflexion du modèle quand il la montre, et chaque appel d&#39;outil avec ses arguments). Les deux ont une vue <strong>Lisible</strong> et une vue <strong>Brut</strong>.</li><li><strong>Une ligne outils</strong> : chaque outil demandé par le modèle, avec ses arguments et le résultat que l&#39;outil a renvoyé dans son appel suivant.</li></ul><p>Chaque ligne a sa propre adresse, par exemple <code>/runs?run=…&amp;row=call-3</code>. <strong>Copier le lien</strong> la met dans le presse-papiers ; l&#39;ouvrir mène à cette ligne. Depuis un appel, <strong>Ouvrir dans la radiographie de l&#39;invite</strong> montre de quoi son invite était faite, et la radiographie renvoie ici.</p><h2 id="ce-qu-elle-ne-peut-pas-voir" tabindex="-1">Ce qu&#39;elle ne peut pas voir <a class="header-anchor" href="#ce-qu-elle-ne-peut-pas-voir" aria-label="Permalink to &quot;Ce qu&#39;elle ne peut pas voir&quot;">​</a></h2><ul><li>L&#39;intérieur des outils. Une requête de base de données au milieu d&#39;un outil fait partie de la ligne outils, pas d&#39;une ligne à elle.</li><li>Le texte des appels enregistrés pendant que <strong>Conserver le texte de l&#39;invite</strong> était désactivé. Les temps restent exacts.</li><li>La réponse d&#39;un appel enregistré avant que le texte conservé ne garde les réponses, quand cet appel terminait une conversation : elle n&#39;est jamais revenue dans un appel ultérieur.</li></ul><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="./live.html">En direct</a> enregistre les appels que dessinent les exécutions.</li><li><a href="./xray.html">Radiographie de l&#39;invite</a> montre de quoi chaque invite était faite.</li></ul>',20)])])}const m=a(l,[["render",r]]);export{g as __pageData,m as default};
